def count_good_sequences(N: int, M: int) -> int:
    """ Count the number of length-M sequences of positive integers whose product is a "good integer" not exceeding N.

    A positive integer n is called a "good integer" if and only if the sum of its positive divisors is divisible by 3.

    The result should be returned modulo 998244353.

    Args:
        N: Upper bound for the product of elements in the sequence (1 <= N <= 10^10)
        M: Length of the sequences (1 <= M <= 10^5)

    Returns:
        The number of valid sequences modulo 998244353

    >>> count_good_sequences(10, 1)
    5
    >>> count_good_sequences(4, 2)
    2
    >>> count_good_sequences(370, 907)
    221764640
    """
    MOD = 998244353

    def is_good(n):
        sum_divisors = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                sum_divisors += i
                if i * i != n:
                    sum_divisors += n // i
        return sum_divisors % 3 == 0

    if M == 1:
        count = 0
        for i in range(1, min(N + 1, 1000)):  # Limit to avoid overflow for larger N and M.
            if is_good(i):
                count += 1
        return count % MOD

    dp = {}

    def solve(current_product, remaining_length):
        if (current_product, remaining_length) in dp:
            return dp[(current_product, remaining_length)]

        if remaining_length == 0:
            if current_product <= N and is_good(current_product):
                return 1
            else:
                return 0

        if current_product > N:
            return 0

        count = 0
        for i in range(1, N // current_product + 1):
            next_product = current_product * i
            if next_product <= N:
                count = (count + solve(next_product, remaining_length - 1)) % MOD

        dp[(current_product, remaining_length)] = count
        return count

    return solve(1, M)
```

