    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid = [[0] * w for _ in range(h)]

    def is_valid(row: int, col: int, tile_height: int, tile_width: int) -> bool:
        if row + tile_height > h or col + tile_width > w:
            return False
        for i in range(row, row + tile_height):
            for j in range(col, col + tile_width):
                if grid[i][j] == 1:
                    return False
        return True

    def place_tile(row: int, col: int, tile_height: int, tile_width: int) -> None:
        for i in range(row, row + tile_height):
            for j in range(col, col + tile_width):
                grid[i][j] = 1

    def remove_tile(row: int, col: int, tile_height: int, tile_width: int) -> None:
        for i in range(row, row + tile_height):
            for j in range(col, col + tile_width):
                grid[i][j] = 0

    def solve(tiles_left: int, sorted_tiles: List[Tuple[int, int]]) -> bool:
        if tiles_left == 0:
            # Check if grid is completely filled.
            for i in range(h):
                for j in range(w):
                    if grid[i][j] == 0:
                        return False
            return True

        for row in range(h):
            for col in range(w):
                if grid[row][col] == 0:
                    for i in range(len(sorted_tiles)):
                        tile_height, tile_width = sorted_tiles[i]
                        # Try both orientations
                        for th, tw in [(tile_height, tile_width), (tile_width, tile_height)]:
                            if is_valid(row, col, th, tw):
