                                if solve(tiles_left - 1, sorted_tiles):
                                    return True
                                remove_tile(row, col, th, tw)
                    return False  # No tile can be placed at this cell
        return False  # No empty cells left

    sorted_tiles = sorted(tiles, key=lambda tile: tile[0] * tile[1], reverse=True)
